-- Generated by `nib db migrate`. Do not edit.
-- The compiler reads this file to check `sql"…"` queries against records, and CI
-- checks that it matches a fresh run of src/migrations.

create table nib_migrations (
	id text primary key,
	checksum bytea not null,
	applied_at timestamptz not null,
	duration_ms int not null,
	toolchain text not null
);

create table nib_queue_messages (
	id uuid primary key,
	queue text not null,
	payload jsonb not null,
	dedup_key text,
	attempts int not null default 0,
	visible_at timestamptz not null,
	created_at timestamptz not null
);

create table nib_queue_dead_letters (
	id uuid primary key,
	queue text not null,
	payload jsonb not null,
	attempts int not null,
	last_error text not null,
	failed_at timestamptz not null
);

create table users (
	id bigint generated always as identity primary key,
	email bytea not null,
	email_idx bytea not null unique,
	password_hash text not null,
	confirmed_at timestamptz,
	created_at timestamptz not null,
	session_version int not null default 1
);

create table user_tokens (
	hash bytea primary key,
	user_id bigint not null references users (id) on delete cascade,
	purpose text not null check (purpose in ('confirm', 'reset_password')),
	expires_at timestamptz not null,
	used_at timestamptz
);

create index user_tokens_user_id on user_tokens (user_id);

create table carts (
	id bigint generated always as identity primary key,
	owner bigint not null references users (id),
	currency text not null,
	address jsonb not null
);

create table cart_lines (
	cart_id bigint not null references carts (id) on delete cascade,
	position int not null,
	sku text not null,
	name text not null,
	quantity int not null check (quantity > 0),
	unit_price numeric(12, 2) not null,
	unit_weight_grams int not null,
	primary key (cart_id, position)
);

create table stock (
	sku text not null,
	warehouse text not null,
	on_hand int not null,
	primary key (sku, warehouse)
);

create sequence order_numbers;

create function next_order_number() returns text as $$
	select 'SHOP-' || case when n < 1000000 then lpad(n::text, 6, '0') else n::text end
	from nextval('order_numbers') as n
$$ language sql;

create table orders (
	id bigint generated always as identity primary key,
	customer bigint not null references users (id),
	status text not null,
	total_amount numeric(12, 2) not null,
	total_currency text not null,
	payment_id text,
	placed_at timestamptz not null,
	number text not null default next_order_number()
);

create unique index orders_number on orders (number);
